function accountStorageKey(userId){return ACCOUNT_DATA_PREFIX+String(userId||'').replace(/[^A-Za-z0-9_-]/g,'_')}
function businessSnapshot(){const copy=JSON.parse(JSON.stringify(d));delete copy.security;return copy}
function save(){
  localStorage.setItem(K,JSON.stringify(d));
  const u=currentAppUser();
  if(u?.id)localStorage.setItem(accountStorageKey(u.id),JSON.stringify(businessSnapshot()));
}
function loadAccountState(user){
  if(!user?.id)return;
  const raw=localStorage.getItem(accountStorageKey(user.id));
  if(raw){try{const business=JSON.parse(raw);d=Object.assign({security:d.security},business);ensureData();return true}catch(e){console.warn('Account data could not be loaded; starting fresh.',e)}}
  // Preserve the original built-in administrator's existing browser data once;
  // every newly created account receives a completely empty business workspace.
  if(String(user.id)==='sa1'){
    localStorage.setItem(accountStorageKey(user.id),JSON.stringify(businessSnapshot()));
    ensureData();
    return false;
  }
  d=Object.assign({security:d.security},freshBusinessState());
  ensureData();
  save();
  return false;
}
const sum=(a,k)=>a.reduce((s,x)=>s+Number(x[k]||0),0);
