function cash(){return sum(d.cash.filter(x=>x.type==='in'),'amount')-sum(d.cash.filter(x=>x.type==='out'),'amount')}
function custBal(id){return Number(d.customers.find(x=>x.id===id)?.opening||0)+sum(d.sales.filter(x=>x.customerId===id),'total')-sum(d.payments.filter(x=>x.type==='customer'&&x.accountId===id),'amount')}
function suppBal(id){return Number(d.suppliers.find(x=>x.id===id)?.opening||0)+sum(d.purchases.filter(x=>x.supplierId===id),'total')-sum(d.payments.filter(x=>x.type==='supplier'&&x.accountId===id),'amount')}
function labourBal(id){return sum(d.workers.filter(x=>x.workerId===id),'wage')-sum(d.payments.filter(x=>x.type==='labour'&&x.accountId===id),'amount')}
function totalStock(){return Object.values(d.stock).reduce((a,b)=>a+Number(b||0),0)}
