function quantityField(){return `<div class="field"><label>Quantity</label><div style="display:flex;gap:6px;align-items:center"><input name="qty" type="number" value="0" min="0" step="1" style="flex:1"><select name="qtyUnit" ondblclick="enableManualQtyUnit(this)" style="width:105px"><option value="kg">kg</option><option value="maund">maund</option><option value="ton">ton</option><option value="trolley">trolley</option><option value="dumper">dumper</option></select></div></div>`}
