function tbl(rows,cols,delType){if(!rows.length)return '<div class="empty">No records yet.</div>';const moneyKeys=['amount','total','wage','rate','paid','advance','advanceReceived','balance'];return `<div class="table"><table><thead><tr>${cols.map(x=>`<th>${x[1]}</th>`).join('')}<th></th></tr></thead><tbody>${rows.map(r=>`<tr>${cols.map(x=>`<td>${x[0]==='date'?formatDate(r[x[0]]):delType==='purchase'&&x[0]==='qty'?(Number(r.qty||0).toLocaleString('en-PK',{maximumFractionDigits:2})+' '+esc(r.qtyUnit||'')):delType==='purchase'&&x[0]==='rate'?(rs(num(r.rate))+' / '+esc(r.ratePer||'unit')):moneyKeys.includes(x[0])?rs(num(r[x[0]])):typeof r[x[0]]==='number'?Number(r[x[0]]).toLocaleString('en-PK',{maximumFractionDigits:2}):esc(r[x[0]])}</td>`).join('')}<td>${delType?`<button class="btn edit-btn" onclick="editRecord('${delType}','${r.id}')">Edit</button> <button class="btn red" onclick="del('${delType}','${r.id}')">Delete</button>`:''}</td></tr>`).join('')}</tbody></table></div>`}
function printLabourLedger(){if(document.getElementById('n-labour')?.classList.contains('on')){document.body.classList.add('print-labour');window.print();setTimeout(()=>document.body.classList.remove('print-labour'),500)}else{window.print()}}
function show(p){
const u=currentAppUser();if(!u){return showAppLogin()}
if(!canViewPage(p)){alert('Access denied. Your account does not have permission to open this section.');return show('dashboard')}
document.querySelectorAll('nav button').forEach(x=>x.classList.remove('on'));document.getElementById('n-'+p)?.classList.add('on');
document.getElementById('title').textContent=(menu.find(x=>x[0]===p)||['',''])[1].replace(/^.\s/,'');
document.getElementById('date').textContent=formatDate(new Date().toISOString().slice(0,10));
document.getElementById('content').innerHTML=(views[p]||views.dashboard)();wire(p);applyViewPermissions(p);updateUserBar();
}
const views={};
views.dashboard=()=>`<div class="cards">
<div class="card"><div class="label">Cash Balance</div><div class="num">${rs(cash())}</div></div>
<div class="card"><div class="label">Sales</div><div class="num">${rs(sum(d.sales,'total'))}</div></div>
<div class="card"><div class="label">Receivables</div><div class="num">${rs(d.customers.reduce((s,x)=>s+Math.max(0,custBal(x.id)),0))}</div></div>
<div class="card"><div class="label">Payables</div><div class="num">${rs(d.suppliers.reduce((s,x)=>s+Math.max(0,suppBal(x.id)),0))}</div></div>
</div><div class="cards">
<div class="card"><div class="label">Purchases</div><div class="num">${rs(sum(d.purchases,'total'))}</div></div>
<div class="card"><div class="label">Expenses</div><div class="num">${rs(sum(d.expenses,'amount'))}</div></div>
<div class="card"><div class="label">Brick Stock</div><div class="num">${totalStock().toLocaleString()}</div></div>
<div class="card"><div class="label">Labour Entries</div><div class="num">${d.workers.length}</div></div></div>
<div class="two"><div class="panel"><h2>Recent Sales</h2>${tbl(d.sales.slice(-8).reverse().map(x=>Object.assign({},x,{brickType:({a:'Awwal',b:'Barshi Awwal',c:'Khinger',d:'Doem',e:'Barshi Doem',f:'Chullah',g:'Chapa',broken:'Broken'}[x.brickType]||x.brickType)})),[['date','Date'],['customerName','Customer'],['brickType','Brick'],['qty','Qty'],['total','Total']],null)}</div>
<div class="panel"><h2>Current Stock</h2>${dashboardStockTbl()}</div></div>`;
function stockTbl(){const labels={kachi:'Katchi',pakki:'Pakki',fired:'Fired',a:'Awwal',b:'Barshi Awwal',c:'Khinger',d:'Doem',e:'Barshi Doem',f:'Chullah',g:'Chapa',broken:'Broken'};const keys=['kachi','pakki','fired','a','b','c','d','e','f','g','broken'];return `<table>${keys.map(k=>`<tr><td>${labels[k]}</td><td class="right">${Number(d.stock[k]||0).toLocaleString()}</td></tr>`).join('')}</table>`}
function dashboardStockTbl(){const labels={kachi:'Katchi',pakki:'Pakki',fired:'Fired',a:'Awwal',b:'Barshi Awwal',c:'Khinger',d:'Doem',e:'Barshi Doem',f:'Chullah',g:'Chapa',broken:'Broken'};const keys=['kachi','pakki','fired','a','b','c','d','e','f','g','broken'];return `<table>${keys.map(k=>`<tr><td>${labels[k]}</td><td class="right">${Number(k==='fired'?(num(d.stock.a)+num(d.stock.b)+num(d.stock.c)+num(d.stock.d)+num(d.stock.e)+num(d.stock.f)+num(d.stock.g)+num(d.stock.broken)):d.stock[k]||0).toLocaleString()}</td></tr>`).join('')}</table>`}
views.cash=()=>form({title:'Cash Transaction',body:inp('Date','date','date',today())+sel('Type','type',[['in','Cash In'],['out','Cash Out']])+inp('Description','description')+inp('Amount (Rs.)','amount','number','0','min="0" step=".01"')},'cashForm','Save Cash Entry')+
`<div class="panel"><h2>Cash Book</h2>${tbl(d.cash.slice().reverse(),[['date','Date'],['type','Type'],['description','Description'],['amount','Amount']],'cash')}<p class="right"><b>Closing Balance: ${rs(cash())}</b></p></div>`;
views.customers=()=>form({title:'New Customer',body:inp('Company / Name','name')+inp('Phone','phone')+inp('Address','address')},'customerForm')+
`<div class="panel"><h2>Customer Profile</h2><div class="table"><table><tr><th>Company / Name</th><th>Phone</th><th>Address</th><th>Actions</th></tr>${d.customers.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.phone||'')}</td><td>${esc(x.address||'')}</td><td><button class="btn edit-btn" onclick="editPartyProfile('customer','${x.id}')">Edit</button> <button class="btn red" onclick="del('customer','${x.id}')">Delete</button></td></tr>`).join('')||'<tr><td colspan=4 class=empty>No customers.</td></tr>'}</table></div></div>`;
views.suppliers=()=>form({title:'New Supplier',body:inp('Company / Name','name')+inp('Phone','phone')+inp('Address','address')+`<div class="field"><label>Item</label><select name="item" ondblclick="enableManualItem(this)" required><option value="">Select item</option><option value="soil">Soil</option><option value="sand">Sand</option><option value="coal">Coal</option><option value="wood">Wood</option></select></div>`},'supplierForm')+
`<div class="panel"><h2>Supplier Profile</h2><div class="table"><table><tr><th>Company / Name</th><th>Phone</th><th>Address</th><th>Item</th><th>Actions</th></tr>${d.suppliers.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.phone||'')}</td><td>${esc(x.address||'')}</td><td>${esc(x.item||'')}</td><td><button class="btn edit-btn" onclick="editPartyProfile('supplier','${x.id}')">Edit</button> <button class="btn red" onclick="del('supplier','${x.id}')">Delete</button></td></tr>`).join('')||'<tr><td colspan=5 class=empty>No suppliers.</td></tr>'}</table></div></div>`;
views.sales=()=>form({title:'Sale / Dispatch',body:sel('Customer','customerId',[['','Cash / Walk-in'],...d.customers.map(x=>[x.id,x.name])]).replace('<select name="customerId">','<select name="customerId" ondblclick="enableManualCustomer(this,event); return false">')+inp('Date','date','date',today())+sel('Brick Type','brickType',[['a','Awwal'],['b','Barshi Awwal'],['c','Khinger'],['d','Doem'],['e','Barshi Doem'],['f','Chullah'],['g','Chapa'],['broken','Broken']])+inp('Quantity (bricks)','qty','number','0','min="0" oninput="onSaleInputsChanged(\'qty\')"')+inp('Rate per Thousand Bricks','rate','number','0','min="0" oninput="onSaleInputsChanged(\'rate\')" ondblclick="unlockSaleRate()" title="Double-click to edit manually when locked"')+inp('Total Amount','total','number','0','min="0" readonly ondblclick="unlockSaleTotal()" oninput="onSaleInputsChanged(\'total\')" title="Double-click to enter manually"')+inp('Received','paid','number','0','min="0" step=".01"')+inp('Advance Received','advanceReceived','number','0','min="0" step=".01"')+inp('Vehicle / Driver','vehicle')+inp('Destination','destination')},'saleForm','Post Sale')+
`<div class="panel sales-register"><h2>Sales Register</h2>${(()=>{const rows=d.sales.slice().reverse().map(x=>Object.assign({},x,{brickType:({a:'Awwal',b:'Barshi Awwal',c:'Khinger',d:'Doem',e:'Barshi Doem',f:'Chullah',g:'Chapa',broken:'Broken'}[x.brickType]||x.brickType),rate:num(x.rate),total:(x.total!==undefined&&x.total!==null&&x.total!==''?num(x.total):(num(x.qty)/1000)*num(x.rate)),paid:num(x.paid),balance:num(x.paid)+num(x.advanceReceived)-(x.total!==undefined&&x.total!==null&&x.total!==''?num(x.total):(num(x.qty)/1000)*num(x.rate))}));const closing=rows.reduce((s,x)=>s+num(x.balance),0);return tbl(rows,[['date','Date'],['customerName','Customer'],['vehicle','Vehicle / Driver'],['destination','Destination'],['brickType','Brick'],['qty','Qty'],['rate','Rate / 1000'],['total','Total Amount'],['paid','Received'],['advanceReceived','Advance Received'],['balance','Balance']],'sale') + `<p class="right"><b>Closing Balance: ${rs(closing)}</b></p>`;})()}</div>`;
views.purchases=()=>form({title:'Purchase',body:sel('Supplier','supplierId',[['','Cash / Walk-in'],...d.suppliers.map(x=>[x.id,x.name])]).replace('<select name="supplierId">','<select name="supplierId" ondblclick="enableManualSupplier(this,event); return false">')+inp('Date','date','date',today())+sel('Item','item',[['soil','Soil'],['sand','Sand'],['coal','Coal'],['wood','Wood']]).replace('<select name="item">','<select name="item" ondblclick="enableManualItem(this)">')+quantityField()+ratePerField()+inp('Paid Now','paid','number','0','min="0" step=".01"')+inp('Advance Payment','advance','number','0','min="0" step=".01"')},'purchaseForm','Post Purchase')+
`<div class="panel"><h2>Purchase Register</h2>${tbl(d.purchases.slice().reverse(),[['date','Date'],['supplierName','Supplier'],['item','Item'],['qty','Qty'],['rate','Rate / Unit'],['total','Total'],['paid','Paid Now'],['advance','Advance Payment'],['balance','Balance']],'purchase')}<p class="right"><b>Closing Balance: ${rs(d.purchases.reduce((s,x)=>s+num(x.total)-num(x.paid)-num(x.advance),0))}</b></p></div>`;
views.daily=()=>form({title:'Daily Production Book',body:inp('Date','date','date',today())+inp('Katchi Produced','kachi','number','0','min="0"')+inp('Pakki Produced','pakki','number','0','min="0"')+inp('Fired','fired','number','0','min="0"')+inp('Awwal','a','number','0','min="0"')+inp('Barshi Awwal','b','number','0','min="0"')+inp('Khinger','c','number','0','min="0"')+inp('Doem','d','number','0','min="0"')+inp('Barshi Doem','e','number','0','min="0"')+inp('Chullah','f','number','0','min="0"')+inp('Chapa','g','number','0','min="0"')+inp('Broken','broken','number','0','min="0"')+inp('Coal/Fuel Used','fuel','number','0','min="0"')+inp('Workers/Teams','teams')+`<div class="field"><label>Notes</label><textarea name="notes"></textarea></div>`},'dailyForm','Post Daily Entry')+
`<div class="panel"><h2>Daily Production Register</h2>${tbl(d.production.slice().reverse(),[['date','Date'],['kachi','Katchi Produced'],['pakki','Pakki Produced'],['fired','Fired'],['a','Awwal'],['b','Barshi Awwal'],['c','Khinger'],['d','Doem'],['e','Barshi Doem'],['f','Chullah'],['g','Chapa'],['broken','Broken'],['fuel','Fuel']],null)}</div>`;
views.labour=()=>form({title:'Labour / Team Ledger Entry',body:inp('Labour / Team Name','name')+inp('Date','date','date',today())+inp('Work Type','work','text','Moulding / Loading / Firing')+inp('Quantity','qty','number','0','min="0"')+inp('Rate per Thousand','rate','number','0','min="0" step=".01"')+inp('Payment','paid','number','0','min="0" step=".01"')+inp('Advance Payment','advance','number','0','min="0" step=".01"')},'labourForm','Post Labour Entry')+
`<div class="panel labour-ledger-print"><h2>Labour Ledger</h2><div class="field" style="max-width:320px;margin-bottom:12px"><label>Labour / Team Filter</label><select onchange="filterLabour(this.value)"><option value="">All Labour / Teams</option>${[...new Set(d.workers.map(x=>x.name))].sort().map(n=>`<option value="${esc(n)}" ${window.labourFilter===n?'selected':''}>${esc(n)}</option>`).join('')}</select></div>${tbl(d.workers.slice().reverse().filter(x=>!window.labourFilter||x.name===window.labourFilter).map(x=>Object.assign({},x,{advance:num(x.advance),balance:num(x.wage)-num(x.paid)-num(x.advance)})),[['date','Date'],['name','Labour Name'],['work','Work'],['qty','Qty'],['rate','Rate / 1000'],['wage','Wage'],['paid','Payment'],['advance','Advance Payment'],['balance','Balance']], 'labour')}<div style="margin-top:14px;text-align:right;font-weight:700;font-size:16px">Closing Balance: ${rs(d.workers.filter(x=>!window.labourFilter||x.name===window.labourFilter).reduce((s,x)=>s+num(x.wage)-num(x.paid)-num(x.advance),0))}</div></div>`;
window.labourFilter=window.labourFilter||'';window.filterLabour=function(v){window.labourFilter=v;show('labour')};
