`<div class="panel"><h2>Super Administrator</h2><p class="muted">Protected security controls for licensing, roles, permissions, audit tracking, database backup configuration, and global configuration.</p><div class="actions"><button class="btn" onclick="openSuperAdmin()">Open Super Admin Settings</button></div></div>`;
function superAdminHTML(){const u=currentSAUser();const lic=activeLicense();const g=d.security.global,b=d.security.backup;return `<div class="sa-shell">
<aside class="sa-side">
<div class="sa-side-title">Administration</div>
<button class="sa-tab active" data-sa-tab="users" onclick="switchSATab('users')"><span>👥</span>User Management</button>
<button class="sa-tab" data-sa-tab="security" onclick="switchSATab('security')"><span>🔐</span>Security & License</button>
<button class="sa-tab" data-sa-tab="logs" onclick="switchSATab('logs')"><span>🧾</span>System Logs</button>
<button class="sa-tab" id="saGlobalConfigTab" data-sa-tab="global" type="button"><span>⚙️</span>Global Config</button>
</aside>
<section class="sa-main">
<div class="sa-page active" data-sa-page="users"><div class="sa-page-head"><div><h3>User Management</h3><p>Manage administrator, manager, operator and cashier accounts.</p></div><span class="sa-status sa-ok">${d.security.users.filter(x=>x.active!==false).length} Active</span></div>
<div class="sa-kpis"><div class="sa-kpi"><small>Total users</small><strong>${d.security.users.length}</strong></div><div class="sa-kpi"><small>Managers</small><strong>${d.security.users.filter(x=>x.role==='Manager').length}</strong></div><div class="sa-kpi"><small>Cashiers</small><strong>${d.security.users.filter(x=>x.role==='Cashier').length}</strong></div></div>
<div class="sa-grid"><div class="sa-box sa-wide"><h3>Accounts</h3>${d.security.users.map(x=>`<div class="sa-user-row"><div class="sa-user-meta"><strong>${esc(x.username)}</strong><small>${esc(x.name)} · <span class="sa-role">${esc(x.role)}</span> · ${x.active?'Active':'Disabled'}</small></div>${x.username!=='admin'?`<button class="btn gray" style="padding:7px 10px" onclick="toggleSAUser('${esc(x.id)}')" ${hasPerm('users.edit')?'':'disabled'}>${x.active?'Disable':'Enable'}</button>`:''}</div>`).join('')}</div>
<div class="sa-box sa-wide"><h3>Create Account</h3><form id="saUserForm"><div class="grid"><div class="field"><label>Username</label><input name="username" required></div><div class="field"><label>Name</label><input name="name" required></div><div class="field"><label>Password</label><input name="password" type="password" minlength="8" required></div><div class="field"><label>Role</label><select name="role">${d.security.roles.map(r=>`<option>${esc(r)}</option>`).join('')}</select></div></div><div class="actions"><button class="btn" ${hasPerm('users.create')?'':'disabled'}>Create Account</button></div></form></div></div></div>

<div class="sa-page" data-sa-page="security"><div class="sa-page-head"><div><h3>Security & License</h3><p>Control license access and feature-level permissions.</p></div><span class="sa-status ${lic?'sa-ok':'sa-danger'}">${lic?'LICENSE ACTIVE':'LICENSE INVALID'}</span></div>
<div class="sa-grid"><div class="sa-box sa-wide"><h3>License Key</h3><div class="sa-license"><div class="field"><label>License Key</label><input id="saLicenseKey" value="${esc(lic?.licenseKey||'')}" placeholder="Enter license key" ${hasPerm('license.manage')?'':'disabled'}></div><div class="field"><label>Expiry Date</label><div class="date-field"><input id="saExpiry" class="date-entry-text" type="text" value="${esc(isoToDateDisplay(lic?.expiresAt||''))}" placeholder="DD-MM-YYYY" inputmode="numeric" autocomplete="off" ${hasPerm('license.manage')?'':'disabled'}><input id="saExpiryPicker" type="date" value="${esc(lic?.expiresAt||'')}" class="date-picker-native" aria-label="Choose expiry date" onchange="syncStandaloneDatePicker(this,'saExpiry')" ${hasPerm('license.manage')?'':'disabled'}></div></div></div><div class="actions"><button class="btn" onclick="saveLicense()" ${hasPerm('license.manage')?'':'disabled'}>Save License</button><button class="btn red" onclick="disableLicense()" ${hasPerm('license.manage')?'':'disabled'}>Disable License</button></div></div>
<div class="sa-box"><h3>Role Permission Matrix</h3><div class="field"><label>Role</label><select id="saRole" onchange="loadRolePerms()">${d.security.roles.map(r=>`<option>${esc(r)}</option>`).join('')}</select></div><div class="sa-perms" id="saPerms" style="margin-top:12px">${SA_PERMISSIONS.map(p=>`<label><input type="checkbox" data-perm="${esc(p)}"> ${esc(p)}</label>`).join('')}</div><div class="actions"><button class="btn green" onclick="saveRolePerms()" ${hasPerm('roles.manage')?'':'disabled'}>Save Permissions</button></div></div>
<div class="sa-box"><h3>Security Controls</h3><label class="sa-switch"><span><b>License enforcement</b><small>Require a valid license for normal operation.</small></span><input type="checkbox" checked disabled></label><label class="sa-switch"><span><b>Audit security changes</b><small>Record role, license and user changes.</small></span><input type="checkbox" checked disabled></label><label class="sa-switch"><span><b>Permission enforcement</b><small>Restrict protected features by assigned permissions.</small></span><input type="checkbox" checked disabled></label></div></div></div>

<div class="sa-page" data-sa-page="logs"><div class="sa-page-head"><div><h3>System Logs</h3><p>Review administrator and security activity.</p></div><span id="auditCount" class="sa-status">0 Records</span></div><div class="sa-box"><div class="grid"><div class="field"><label>User</label><input id="auditUser" placeholder="Username" autocomplete="off"></div><div class="field"><label>Action</label><input id="auditAction" placeholder="e.g. LOGIN" autocomplete="off"></div><div class="field"><label>Date</label><div class="date-field"><input id="auditDate" class="date-entry-text" type="text" placeholder="DD-MM-YYYY" inputmode="numeric" autocomplete="off"><input id="auditDatePicker" type="date" class="date-picker-native" aria-label="Choose filter date" onchange="syncStandaloneDatePicker(this,'auditDate')"></div></div></div><div class="actions"><button class="btn gray" onclick="renderAuditLogs()" ${hasPerm('audit_logs.view')?'':'disabled'}>Filter Logs</button><button class="btn" onclick="clearAuditFilters()" ${hasPerm('audit_logs.view')?'':'disabled'}>Clear Filters</button></div><div id="auditResults" class="sa-table-wrap sa-log-table" style="margin-top:14px"></div></div></div>

<div class="sa-page" data-sa-page="global"><div class="sa-page-head"><div><h3>Global Config</h3><p>System-wide settings and database backup controls.</p></div></div><div class="sa-grid"><div class="sa-box"><h3>Global Configuration</h3><div class="grid"><div class="field"><label>Currency</label><select id="saCurrency"><option ${g.currency==='PKR'?'selected':''}>PKR</option><option ${g.currency==='USD'?'selected':''}>USD</option><option ${g.currency==='AED'?'selected':''}>AED</option><option ${g.currency==='SAR'?'selected':''}>SAR</option></select></div><div class="field"><label>Tax</label><select id="saTaxEnabled"><option value="false" ${!g.taxEnabled?'selected':''}>Disabled</option><option value="true" ${g.taxEnabled?'selected':''}>Enabled</option></select></div><div class="field"><label>Tax Rate (%)</label><input id="saTaxRate" type="number" min="0" max="100" step="0.01" value="${Number(g.taxRate)||0}"></div></div><label class="sa-switch"><span><b>Maintenance Mode</b><small>Temporarily prevent normal users from accessing the system.</small></span><input id="saMaintenance" type="checkbox" ${g.maintenanceMode?'checked':''}></label><div class="actions"><button class="btn" onclick="saveGlobalSettings()" ${hasPerm('settings.manage')?'':'disabled'}>Save Global Configuration</button></div></div>
<div class="sa-box"><h3>Database Backup</h3><label class="sa-switch"><span><b>Automatic Backup</b><small>Configure automatic backup behavior.</small></span><input id="saBackupEnabled" type="checkbox" ${b.enabled?'checked':''}></label><div class="grid"><div class="field"><label>Frequency</label><select id="saBackupFrequency"><option ${b.frequency==='Daily'?'selected':''}>Daily</option><option ${b.frequency==='Weekly'?'selected':''}>Weekly</option><option ${b.frequency==='Monthly'?'selected':''}>Monthly</option></select></div><div class="field"><label>Time</label><input id="saBackupTime" type="time" value="${esc(b.time)}"></div><div class="field"><label>Retention (days)</label><input id="saRetention" type="number" min="1" value="${Number(b.retentionDays)||30}"></div></div><label class="sa-switch"><span><b>Backup Encryption</b><small>Mark generated backups for encrypted storage.</small></span><input id="saBackupEncrypted" type="checkbox" ${b.encrypted?'checked':''}></label><div class="actions"><button class="btn" onclick="saveBackupSettings()" ${hasPerm('backup.create')?'':'disabled'}>Save Backup Settings</button><button class="btn gray" onclick="createLocalBackup()" ${hasPerm('backup.create')?'':'disabled'}>Create Backup Now</button></div></div></div></div>
</section></div>`}
function setSAContentState(type,message){const main=document.querySelector('#saPanel .sa-main');if(!main)return;let el=document.getElementById('saContentState');if(!el){el=document.createElement('div');el.id='saContentState';el.style.cssText='display:none;margin:0 0 14px;padding:12px 14px;border:1px solid #e2e8f0;border-radius:10px;background:#fff;color:#334155;font-size:13px';main.prepend(el)}el.style.display=type?'block':'none';el.textContent=message||'';el.dataset.state=type||''}
function switchSATab(tab){try{setSAContentState('loading','Loading '+(tab==='global'?'Global Config':tab==='security'?'Security & License':tab==='logs'?'System Logs':'User Management')+'…');const tabs=document.querySelectorAll('.sa-tab');const pages=document.querySelectorAll('.sa-page');let target=null;pages.forEach(x=>{const match=x.dataset.saPage===tab;x.classList.toggle('active',match);if(match)target=x});tabs.forEach(x=>x.classList.toggle('active',x.dataset.saTab===tab));if(!target)throw new Error('Admin page not found: '+tab);if(tab==='global'){const currency=document.getElementById('saCurrency');if(!currency)throw new Error('Global Config controls failed to render.')}if(tab==='logs')renderAuditLogs();requestAnimationFrame(()=>setSAContentState('', ''));}catch(err){console.error('Administrator tab render error:',err);setSAContentState('error','Unable to load this section. The rest of the Admin Panel is still available.');const pages=document.querySelectorAll('.sa-page');pages.forEach(x=>x.classList.remove('active'));const target=document.querySelector('.sa-page[data-sa-page="'+tab+'"]');if(target)target.classList.add('active')}}

function safeRenderSuperAdmin(){try{setSAContentState('loading','Loading Administrator Control Panel…');renderSuperAdmin();requestAnimationFrame(()=>setSAContentState('',''));}catch(err){console.error('Administrator Control Panel render error:',err);setSAContentState('error','Administrator panel could not render this section. Please try the tab again.');}}

function openSuperAdmin(){document.getElementById('saLogin').classList.add('show');document.getElementById('saLoginForm').reset()}
function closeSA(){document.getElementById('saLogin').classList.remove('show');document.getElementById('saPanel').classList.remove('show')}
async function doSALogin(e){
  e.preventDefault();
  const x=Object.fromEntries(new FormData(e.target));
  const username=String(x.username||'').trim().toLowerCase();
  const u=d.security.users.find(z=>String(z.username||'').trim().toLowerCase()===username&&z.active!==false);
  if(!u)return alert('Invalid username or password.');
  const h=await hashText(String(x.password||''));
  if(String(u.passwordHash||'')!==h)return alert('Invalid username or password.');
  sessionStorage.setItem('BHATTA_SA_SESSION',JSON.stringify({id:u.id,username:u.username,role:u.role}));
  audit('LOGIN','Security',u.username,'Super Admin authentication');
  document.getElementById('saLogin').classList.remove('show');
  document.getElementById('saPanel').classList.add('show');
  safeRenderSuperAdmin();
}
function bindGlobalConfigTab(){const tab=document.getElementById('saGlobalConfigTab');if(!tab||tab.dataset.bound==='1')return;if(!tab.dataset.bound){tab.addEventListener('click',function(){try{const main=document.querySelector('#saPanel .sa-main');if(!main)throw new Error('Admin content area not found.');setSAContentState('loading','Loading Global Config…');renderSuperAdmin();switchSATab('global');requestAnimationFrame(()=>setSAContentState('',''));}catch(err){console.error('Global Config render error:',err);setSAContentState('error','Unable to load Global Config. Please try again.');}});tab.dataset.bound='1';}}
function renderSuperAdmin(){document.getElementById('saContent').innerHTML=superAdminHTML();bindGlobalConfigTab();loadRolePerms();renderAuditLogs();const f=document.getElementById('saUserForm');if(f)f.onsubmit=async e=>{e.preventDefault();if(!hasPerm('users.create'))return alert('Access denied.');const x=Object.fromEntries(new FormData(e.target));if(d.security.users.some(u=>u.username.toLowerCase()===x.username.toLowerCase()))return alert('Username already exists.');const ph=await hashText(x.password);d.security.users.push({id:uid(),username:x.username.trim(),name:x.name.trim(),role:x.role,passwordHash:ph,active:true});audit('USER_CREATED','Security',x.username,'Role: '+x.role);save();renderSuperAdmin();}}
function loadRolePerms(){const r=document.getElementById('saRole')?.value;if(!r)return;const set=new Set(d.security.rolePermissions[r]||[]);document.querySelectorAll('#saPerms [data-perm]').forEach(c=>c.checked=set.has(c.dataset.perm))}
function saveRolePerms(){if(!hasPerm('roles.manage'))return alert('Access denied.');const r=document.getElementById('saRole').value;const perms=[...document.querySelectorAll('#saPerms [data-perm]:checked')].map(x=>x.dataset.perm);if(r==='Super Administrator')return alert('The Super Administrator role cannot be reduced.');d.security.rolePermissions[r]=perms;audit('PERMISSION_CHANGED','Security',r,perms.join(', '));save();renderSuperAdmin()}
function renderAuditLogs(){const box=document.getElementById('auditResults');if(!box)return;const u=(document.getElementById('auditUser')?.value||'').trim().toLowerCase(),a=(document.getElementById('auditAction')?.value||'').trim().toLowerCase(),dt=dateDisplayToISO(document.getElementById('auditDate')?.value||'');const rows=d.security.auditLogs.slice().reverse().filter(x=>(!u||String(x.user||'').toLowerCase().includes(u))&&(!a||String(x.action||'').toLowerCase().includes(a))&&(!dt||String(x.date||'').slice(0,10)===dt));const count=document.getElementById('auditCount');if(count)count.textContent=rows.length.toLocaleString('en-PK')+' '+(rows.length===1?'Record':'Records');box.innerHTML=`<table><thead><tr><th>#</th><th>Date & Time</th><th>User</th><th>Action</th><th>Module</th><th>Details</th></tr></thead><tbody>${rows.slice(0,200).map((x,i)=>`<tr><td>${i+1}</td><td>${formatDate(x.date)}</td><td>${esc(x.user||'System')}</td><td><span class="sa-log-action">${String(x.action||'—').split(/(\s+)/).map(part=>/^\s+$/.test(part)?part:`<span class="sa-log-word">${esc(part)}</span>`).join('')}</span></td><td>${esc(x.module||'—')}</td><td>${esc(x.details||'—')}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No matching audit records.</td></tr>'}</tbody></table>${rows.length>200?`<div class="sa-log-note">Showing the latest 200 matching records.</div>`:''}`}
function clearAuditFilters(){['auditUser','auditAction','auditDate','auditDatePicker'].forEach(id=>{const el=document.getElementById(id);if(el)el.value=''});renderAuditLogs()}
function toggleSAUser(id){if(!hasPerm('users.edit'))return alert('Access denied.');const x=d.security.users.find(u=>u.id===id);if(!x||x.username==='admin')return;x.active=x.active===false;audit(x.active?'USER_ENABLED':'USER_DISABLED','Security',x.username,'Account status changed');save();renderSuperAdmin()}
function disableLicense(){if(!hasPerm('license.manage'))return alert('Access denied.');const l=activeLicense();if(!l)return alert('No active license found.');l.active=false;audit('LICENSE_DISABLED','Security',l.licenseKey,'License disabled');save();renderSuperAdmin()}
function saveLicense(){if(!hasPerm('license.manage'))return alert('Access denied.');let l=activeLicense()||d.security.licenses[0];if(!l){l={id:uid(),active:true};d.security.licenses.push(l)}l.licenseKey=document.getElementById('saLicenseKey').value.trim();l.expiresAt=dateDisplayToISO(document.getElementById('saExpiry').value)||'';l.active=true;audit('LICENSE_CHANGED','Security',l.licenseKey,'Expiry: '+l.expiresAt);save();renderSuperAdmin()}
function saveBackupSettings(){if(!hasPerm('backup.create'))return alert('Access denied.');d.security.backup={enabled:document.getElementById('saBackupEnabled').checked,frequency:document.getElementById('saBackupFrequency').value,time:document.getElementById('saBackupTime').value,retentionDays:Number(document.getElementById('saRetention').value)||30,encrypted:document.getElementById('saBackupEncrypted').checked,lastBackupAt:d.security.backup.lastBackupAt||''};audit('BACKUP_SETTINGS_CHANGED','Security','Backup',JSON.stringify(d.security.backup));save();renderSuperAdmin()}
function createLocalBackup(){if(!hasPerm('backup.create'))return alert('Access denied.');d.security.backup.lastBackupAt=new Date().toISOString();audit('BACKUP_CREATED','Security','Local JSON','Manual backup created');save();backup()}
function saveGlobalSettings(){if(!hasPerm('settings.manage'))return alert('Access denied.');d.security.global={currency:document.getElementById('saCurrency').value,taxEnabled:document.getElementById('saTaxEnabled').value==='true',taxRate:Number(document.getElementById('saTaxRate').value)||0,maintenanceMode:document.getElementById('saMaintenance').checked};d.settings.currency=d.security.global.currency;audit('GLOBAL_SETTINGS_CHANGED','Settings','Global',JSON.stringify(d.security.global));save();applyMaintenanceMode();show('settings');renderSuperAdmin()}
function applyMaintenanceMode(){const el=document.getElementById('maintenanceOverlay');if(el)el.classList.toggle('show',!!d.security?.global?.maintenanceMode&&!currentSAUser())}
function validAmount(n){return Number.isFinite(Number(n))&&Number(n)>=0}
function num(v){let n=Number(v);return Number.isFinite(n)?n:0}
function saleTotal(x){return (num(x.qty)/1000)*num(x.rate)}
function postCash(date,type,description,amount){amount=num(amount);if(!amount)return null;let x={id:uid(),date:date||today(),type,description:description||'',amount};d.cash.push(x);return x}
function postPayment(date,type,accountId,amount){amount=num(amount);if(!amount||!accountId)return null;let x={id:uid(),date:date||today(),type,accountId,amount};d.payments.push(x);return x}
function refresh(){save();show(Object.keys(views).find(x=>document.getElementById('n-'+x)?.classList.contains('on'))||'dashboard')}
function ensureData(){
  d.customers=d.customers||[];d.suppliers=d.suppliers||[];d.workers=d.workers||[];d.sales=d.sales||[];d.purchases=d.purchases||[];d.payments=d.payments||[];d.cash=d.cash||[];d.production=d.production||[];d.expenses=d.expenses||[];d.vehicles=d.vehicles||[];d.fuel=d.fuel||[];d.users=d.users||[];d.logs=d.logs||[];
  d.stock=Object.assign({kachi:0,pakki:0,fired:0,a:0,b:0,c:0,d:0,e:0,f:0,g:0,broken:0},d.stock||{});
  d.settings=Object.assign({name:'My Bhatta',owner:'',phone:'',address:'Lahore, Punjab, Pakistan',currency:'PKR'},d.settings||{});initSecurity();
}
ensureData();
function currentAppUser(){return JSON.parse(sessionStorage.getItem('BHATTA_APP_SESSION')||'null')}
function canViewPage(p){const u=currentAppUser();if(!u)return false;if(u.role==='Super Administrator'||u.role==='Administrator')return true;const map={dashboard:'dashboard.view',cash:'dashboard.view',daily:'daily_book.view',sales:'sales.view',purchases:'purchase.view',khata:'khata.view',labour:'labour_khata.view',stock:'dashboard.view',expenses:'reports.view',customers:'khata.view',suppliers:'khata.view',vehicles:'purchase.view',fuel:'purchase.view',reports:'reports.view',ai:'dashboard.view',account:'dashboard.view',users:'users.view',settings:'settings.view'};return (d.security.rolePermissions[u.role]||[]).includes(map[p]||'')}
function canEditPage(p){const u=currentAppUser();if(!u)return false;if(u.role==='Super Administrator'||u.role==='Administrator')return true;const map={cash:'cash.create',daily:'daily_book.create',sales:'sales.create',purchases:'purchase.create',khata:'khata.create',labour:'labour_khata.create',stock:'dashboard.view',expenses:'reports.export',customers:'khata.create',suppliers:'khata.create',vehicles:'purchase.create',fuel:'purchase.create',users:'users.edit',settings:'settings.manage'};return (d.security.rolePermissions[u.role]||[]).includes(map[p]||'')}
function applyViewPermissions(p){const editable=canEditPage(p);document.querySelectorAll('#content form:not(#aiForm):not(#accountForm)').forEach(f=>{if(!editable){f.querySelectorAll('input,select,textarea,button').forEach(el=>el.disabled=true);const n=document.createElement('div');n.className='notice';n.style.marginBottom='10px';n.textContent='View-only access for your account.';f.parentElement.insertBefore(n,f)}});if(!canViewPage('users'))document.querySelector('#n-users')?.remove();if(!canViewPage('settings'))document.querySelector('#n-settings')?.remove();document.querySelectorAll('#content .btn.red').forEach(b=>{if(!editable)b.disabled=true})}
function updateUserBar(){const top=document.querySelector('.top .actions');if(!top)return;const u=currentAppUser();top.querySelector('.user-menu-bar')?.remove();if(!u)return;const wrap=document.createElement('div');wrap.className='user-menu-bar';wrap.innerHTML=`<span class="user-pill">👤 ${esc(u.username)} · ${esc(u.role)}</span><button class="logout-btn" onclick="appLogout()">Logout</button>`;top.appendChild(wrap)}
function populateLoginRoles(){const sel=document.getElementById('appLoginRole');if(!sel||!d.security)return;const current=sel.value;sel.innerHTML='<option value="">Select your role</option>'+d.security.roles.map(r=>'<option value="'+esc(r)+'">'+esc(r)+'</option>').join('');if(current&&d.security.roles.includes(current))sel.value=current}
function showAppLogin(){document.body.classList.add('auth-locked');document.getElementById('appLogin')?.classList.remove('hidden');document.getElementById('appLoginForm')?.reset();populateLoginRoles();updatePasswordStrength('')}
function hideAppLogin(){document.body.classList.remove('auth-locked');document.getElementById('appLogin')?.classList.add('hidden')}
function toggleAppPassword(){const x=document.getElementById('appPassword');if(!x)return;x.type=x.type==='password'?'text':'password'}
const LOGIN_EFFECTS=[['aurora','Aurora'],['crystal','Crystal'],['pulse','Pulse'],['flow','Flow']];
let loginEffectIndex=0;
function cycleLoginEffect(){const root=document.getElementById('appLogin');if(!root)return;root.classList.remove(...LOGIN_EFFECTS.map(x=>'effect-'+x[0]));loginEffectIndex=(loginEffectIndex+1)%LOGIN_EFFECTS.length;const effect=LOGIN_EFFECTS[loginEffectIndex];if(effect[0]!=='aurora')root.classList.add('effect-'+effect[0]);const label=document.getElementById('loginEffectLabel');if(label)label.textContent=effect[1]+' • tap arrow';const arrow=document.getElementById('loginEffectArrow');if(arrow){arrow.animate([{transform:'translate(-50%,-50%) rotate(0deg)'},{transform:'translate(-50%,-50%) rotate(180deg)'},{transform:'translate(-50%,-50%) rotate(360deg)'}],{duration:420,easing:'ease-out'});}}

function updatePasswordStrength(v){let score=0;if(v.length>=8)score+=25;if(/[a-z]/.test(v))score+=15;if(/[A-Z]/.test(v))score+=15;if(/\d/.test(v))score+=15;if(/[^A-Za-z0-9]/.test(v))score+=20;if(v.length>=12)score+=10;score=Math.min(100,score);const m=document.getElementById('passwordMeter'),p=document.getElementById('passwordPercent'),t=document.getElementById('passwordStrength');if(m)m.style.width=score+'%';if(p)p.textContent=score+'%';if(t)t.textContent=score<35?'Weak password':score<65?'Fair password':score<85?'Strong password':'Very strong password';const ring=document.getElementById('passwordRing');if(ring){ring.style.setProperty('--strength',score+'%');const b=ring.querySelector('b');if(b)b.textContent=score+'%'}}
async function doAppLogin(e){
  e.preventDefault();
  const x=Object.fromEntries(new FormData(e.target));
  const err=document.getElementById('appLoginError');
  if(err){err.style.display='none';err.textContent='';}
  const username=String(x.username||'').trim().toLowerCase();
  const password=String(x.password||'');
  const role=String(x.role||'').trim();
  const u=d.security.users.find(z=>String(z.username||'').trim().toLowerCase()===username&&z.active!==false);
  if(!role){if(err){err.textContent='Please select your role.';err.style.display='block';}return;} 
  if(!u){if(err){err.textContent='Invalid username, role or password.';err.style.display='block';}return;}
  if(String(u.role||'')!==role){if(err){err.textContent='The selected role does not match this account.';err.style.display='block';}return;}
  if(!u){if(err){err.textContent='Invalid username or password.';err.style.display='block';}return;}
  const h=await hashText(password);
  if(String(u.passwordHash||'')!==h){if(err){err.textContent='Invalid username or password.';err.style.display='block';}return;}
  sessionStorage.setItem('BHATTA_APP_SESSION',JSON.stringify({id:u.id,username:u.username,name:u.name,role:u.role}));
  sessionStorage.setItem('BHATTA_SA_SESSION',JSON.stringify({id:u.id,username:u.username,role:u.role}));
  loadAccountState(u);
  audit('LOGIN','Authentication',u.username,'Application login');
  hideAppLogin();
  buildNav();
  show('dashboard');
}
function appLogout(){const u=currentAppUser();if(u){save();audit('LOGOUT','Authentication',u.username,'Application logout')}sessionStorage.removeItem('BHATTA_APP_SESSION');sessionStorage.removeItem('BHATTA_SA_SESSION');showAppLogin()}
function buildNav(){const nav=document.getElementById('nav');if(!nav)return;nav.innerHTML=menu.filter(x=>canViewPage(x[0])).map(x=>`<button id="n-${x[0]}" onclick="show('${x[0]}')">${x[1]}</button>`).join('')}
function localAI(q){const s=String(q||'').toLowerCase(),sales=sum(d.sales,'total'),purchases=sum(d.purchases,'total'),expenses=sum(d.expenses,'amount'),cashBal=cash(),receivables=d.customers.reduce((a,x)=>a+Math.max(0,custBal(x.id)),0),payables=d.suppliers.reduce((a,x)=>a+Math.max(0,suppBal(x.id)),0),stock=d.stock,labour=d.workers.reduce((a,x)=>a+Math.max(0,num(x.wage||x.total||0)-num(x.paid||0)),0),customers=d.customers.length,suppliers=d.suppliers.length,margin=sales-purchases-expenses;let out='';if(s.includes('stock'))out=`Stock Intelligence\n\nKatchi: ${Number(stock.kachi||0).toLocaleString()} bricks\nPakki: ${Number(stock.pakki||0).toLocaleString()} bricks\nFired: ${Number(stock.fired||0).toLocaleString()} bricks\nAwwal: ${Number(stock.a||0).toLocaleString()}\nBarshi Awwal: ${Number(stock.b||0).toLocaleString()}\nKhinger: ${Number(stock.c||0).toLocaleString()}\nDoem: ${Number(stock.d||0).toLocaleString()}\nBarshi Doem: ${Number(stock.e||0).toLocaleString()}\nChullah: ${Number(stock.f||0).toLocaleString()}\nChapa: ${Number(stock.g||0).toLocaleString()}\nBroken: ${Number(stock.broken||0).toLocaleString()}\n\nTotal tracked stock: ${totalStock().toLocaleString()} bricks.\nRecommendation: keep production transfers within the available stage stock to avoid validation failures.`;else if(s.includes('cash')||s.includes('receivable')||s.includes('payment'))out=`Financial Intelligence\n\nCash balance: ${rs(cashBal)}\nCustomer receivables: ${rs(receivables)}\nSupplier payables: ${rs(payables)}\nOutstanding labour: ${rs(labour)}\n\nRecommendation: review the largest outstanding customer and supplier balances before extending further credit.`;else if(s.includes('labour')||s.includes('worker'))out=`Labour Intelligence\n\nWorkers/teams recorded: ${d.workers.length.toLocaleString()}\nOutstanding labour balance: ${rs(labour)}\n\nUse the Labour Khata section to inspect individual ledgers and payments.`;else if(s.includes('customer'))out=`Customer Intelligence\n\nCustomers: ${customers.toLocaleString()}\nReceivables: ${rs(receivables)}\nSales value: ${rs(sales)}\n\nRecommendation: use customer ledgers to identify overdue balances and recent activity.`;else if(s.includes('supplier'))out=`Supplier Intelligence\n\nSuppliers: ${suppliers.toLocaleString()}\nPayables: ${rs(payables)}\nPurchases: ${rs(purchases)}\n\nRecommendation: review supplier balances and payment history in Khata Book.`;else if(s.includes('sale')||s.includes('purchase')||s.includes('business')||s.includes('profit'))out=`Business Intelligence\n\nSales: ${rs(sales)}\nPurchases: ${rs(purchases)}\nExpenses: ${rs(expenses)}\nOperating result: ${rs(margin)}\n\nStatus: ${margin>=0?'Positive operating result.':'Operating result needs attention.'}\nRecommendation: compare sales, purchase costs, expenses and outstanding balances before major decisions.`;else out=`Bhatta Management Intelligence\n\nSales: ${rs(sales)}\nPurchases: ${rs(purchases)}\nExpenses: ${rs(expenses)}\nCash: ${rs(cashBal)}\nReceivables: ${rs(receivables)}\nPayables: ${rs(payables)}\nLabour outstanding: ${rs(labour)}\nStock: ${totalStock().toLocaleString()} bricks\nCustomers: ${customers.toLocaleString()} · Suppliers: ${suppliers.toLocaleString()}\n\nI can analyze stock, fired grades, cash, payments, sales, purchases, labour, customers, suppliers and the overall operating result.`;return out}
function askAI(q){const box=document.getElementById('aiAnswer');if(box)box.textContent=localAI(q)}
function wire(p){
const f=id=>document.getElementById(id);
if(p==='ai'){const af=f('aiForm');if(af)af.onsubmit=e=>{e.preventDefault();const x=Object.fromEntries(new FormData(e.target));askAI(x.question)}}
if(p==='account'){const af=f('accountForm');if(af)af.onsubmit=async e=>{e.preventDefault();const x=Object.fromEntries(new FormData(e.target));const u=d.security.users.find(z=>z.id===currentAppUser()?.id);if(!u)return;const name=x.name.trim(),username=x.username.trim();if(!name||!username)return alert('Enter name and username.');if(d.security.users.some(z=>z.id!==u.id&&z.username.toLowerCase()===username.toLowerCase()))return alert('Username already exists.');u.name=name;u.username=username;if(x.password){if(x.password.length<8)return alert('Password must be at least 8 characters.');u.passwordHash=await hashText(x.password)}const sess=currentAppUser();sess.name=name;sess.username=username;sessionStorage.setItem('BHATTA_APP_SESSION',JSON.stringify(sess));sessionStorage.setItem('BHATTA_SA_SESSION',JSON.stringify({id:u.id,username:u.username,role:u.role}));audit('ACCOUNT_UPDATED','Authentication',u.username,'Own profile updated');save();alert('Account updated successfully.');show('account')}}
if(p==='cash')f('cashForm').onsubmit=e=>{e.preventDefault();let x=Object.fromEntries(new FormData(e.target));x.amount=num(x.amount);if(!validAmount(x.amount)||x.amount<=0)return alert('Enter a valid amount greater than 0.');d.cash.push({id:uid(),date:x.date||today(),type:x.type,description:x.description||'',amount:x.amount});log('Cash '+x.type,x.description||'Manual entry');refresh()}
if(p==='customers')f('customerForm').onsubmit=e=>{e.preventDefault();let x=Object.fromEntries(new FormData(e.target));x.name=String(x.name||'').trim();if(!x.name)return alert('Enter company / customer name.');x.id=uid();d.customers.push(x);log('Customer created',x.name);refresh()}
if(p==='suppliers')f('supplierForm').onsubmit=e=>{e.preventDefault();let x=Object.fromEntries(new FormData(e.target));x.name=String(x.name||'').trim();if(!x.name)return alert('Enter company / supplier name.');x.item=String(x.item||'').trim();if(!x.item)return alert('Select or enter a supplier item.');x.id=uid();d.suppliers.push(x);log('Supplier created',x.name);refresh()}
if(p==='sales')f('saleForm').onsubmit=e=>{e.preventDefault();let x=Object.fromEntries(new FormData(e.target));if(x.customerManual){x.customerName=x.customerManual.trim();x.customerId=d.customers.find(c=>c.name.trim().toLowerCase()===x.customerName.toLowerCase())?.id||''}else{x.customerName=x.customerId?(d.customers.find(c=>c.id===x.customerId)?.name||''):'Cash / Walk-in'};x.qty=num(x.qty);x.rate=num(x.rate);x.paid=num(x.paid);x.advanceReceived=num(x.advanceReceived);if(x.advanceReceived>0&&!x.customerId)return alert('Advance Received is not allowed for Cash / Walk-in customer.');const totalBox=e.target.querySelector('[name="total"]');if(totalBox?.dataset.manual!=='1')x.total=(x.qty/1000)*x.rate;else x.total=num(x.total);x.date=x.date||today();/* Handle received-only customer balance payments before general zero-entry checks; ignore any stale/manual Total Amount when quantity and rate are zero. */if(x.paid>0&&x.qty===0&&x.rate===0&&x.advanceReceived===0){if(!x.customerId)return alert('Select a registered customer to record a payment against their outstanding balance.');x.total=0;if(x.paid<0)return alert('Received amount cannot be negative.');const previousRemaining=d.sales.filter(s=>s.customerId===x.customerId).reduce((sum,s)=>{const saleTotal=(s.total!==undefined&&s.total!==null&&s.total!=='')?num(s.total):(num(s.qty)/1000)*num(s.rate);return sum+saleTotal-num(s.paid)-num(s.advanceReceived)},0);if(previousRemaining<=0)return alert('This customer has no outstanding balance to receive against.');if(x.paid>previousRemaining+0.000001)return alert('Received amount cannot be greater than the customer’s previous remaining balance of Rs '+previousRemaining.toLocaleString('en-PK',{maximumFractionDigits:2})+'.');x.id=uid();x.isPaymentOnly=true;d.sales.push(x);let c=postCash(x.date,'in','Customer balance payment - '+x.customerName,x.paid);x.paidCashId=c?.id||'';let pm=postPayment(x.date,'customer',x.customerId,x.paid);x.paidPaymentId=pm?.id||'';log('Customer balance payment received',x.customerName+' - Rs '+x.paid.toLocaleString());refresh();return;}if(x.qty===0&&x.rate===0&&x.paid===0&&x.advanceReceived===0&&num(x.total)===0)return alert('Entry not saved: all quantities and amounts are zero.');if(x.paid>0&&(x.qty<=0||x.rate<=0))return alert('Enter Quantity and Rate before entering or posting Received.');if(!x.customerId&&x.paid!==x.total)return alert('Received must be the full Total Amount for Cash / Walk-in customer.');
  if(x.advanceReceived>0&&x.qty===0&&x.rate===0&&x.paid===0){if(!x.customerName)return alert('Enter customer name for advance received.');x.id=uid();x.isAdvanceOnly=true;d.sales.push(x);let c=postCash(x.date,'in','Customer advance - '+x.customerName,x.advanceReceived);x.advanceCashId=c?.id||'';if(x.customerId){let pm=postPayment(x.date,'customer',x.customerId,x.advanceReceived);x.advancePaymentId=pm?.id||''}log('Customer advance received',x.customerName);refresh();return;}
  if(x.qty<0||x.rate<0)return alert('Enter a valid quantity and rate.');
  if(x.paid<0||x.paid>x.total)return alert('Received cannot be greater than the sale total.');
  let stockKey=x.brickType;
  if(!stockKey)return alert('Select a brick type.');
  d.stock.c=num(d.stock.c);d.stock.d=num(d.stock.d);d.stock[stockKey]=num(d.stock[stockKey]);
  if(x.qty>d.stock[stockKey]){let stockName=({a:'Awwal',b:'Barshi Awwal',c:'Khinger',d:'Doem',e:'Barshi Doem',f:'Chullah',g:'Chapa',broken:'Broken'}[stockKey]||'brick');return alert(stockName+' stock exceeded. Available '+stockName+' stock: '+d.stock[stockKey].toLocaleString()+' bricks. Requested for sale: '+x.qty.toLocaleString()+' bricks. Excess: '+(x.qty-d.stock[stockKey]).toLocaleString()+' bricks.')}
  x.id=uid();d.sales.push(x);d.stock[stockKey]-=x.qty;
  if(x.paid){let c=postCash(x.date,'in','Sale payment - '+x.customerName,x.paid);x.paidCashId=c?.id||'';if(x.customerId){let pm=postPayment(x.date,'customer',x.customerId,x.paid);x.paidPaymentId=pm?.id||''}}
  if(x.advanceReceived){let c=postCash(x.date,'in','Customer advance - '+x.customerName,x.advanceReceived);x.advanceCashId=c?.id||'';if(x.customerId){let pm=postPayment(x.date,'customer',x.customerId,x.advanceReceived);x.advancePaymentId=pm?.id||''}}
  log('Sale posted',x.customerName);refresh()}
if(p==='purchases')f('purchaseForm').onsubmit=e=>{e.preventDefault();let x=Object.fromEntries(new FormData(e.target));x.qty=num(x.qty);x.rate=num(x.rate);x.paid=num(x.paid);x.advance=num(x.advance);x.total=x.qty*x.rate;x.balance=x.total-x.paid-x.advance;x.date=x.date||today();if(x.supplierManual){x.supplierName=x.supplierManual.trim();const existing=d.suppliers.find(c=>c.name.toLowerCase()===x.supplierName.toLowerCase());x.supplierId=existing?.id||''}else{x.supplierName=x.supplierId?(d.suppliers.find(c=>c.id===x.supplierId)?.name||''):'Cash / Walk-in';}
  if(x.qty===0&&x.rate===0&&x.paid===0&&x.advance===0)return alert('Entry not saved: all quantities and amounts are zero.');
  if(x.qty<0||x.rate<0)return alert('Enter a valid quantity and rate.');
  if(x.paid<0||x.advance<0)return alert('Paid Now and Advance Payment cannot be negative.');
  if(x.paid>0&&(x.qty<=0||x.rate<=0))return alert('Enter Quantity and Rate before entering or posting Paid Now.');
  if(x.advance>0&&!x.supplierId)return alert('Advance Payment is not allowed for Cash / Walk-in supplier. Select a registered supplier to use Advance Payment.');
  if(x.total>0&&x.paid+x.advance>x.total)return alert('Paid Now plus Advance Payment cannot be greater than the purchase total.');
  if(!x.supplierId&&x.paid!==x.total)return alert('Cash / Walk-in purchases must be fully paid in Paid Now. Advance Payment is not allowed. Enter Quantity and Rate first, then set Paid Now equal to the full purchase total, or select a registered supplier for a credit purchase.');
  x.id=uid();d.purchases.push(x);
  // Keep Dashboard Current Stock synchronized for brick-stock purchases without changing the Purchase UI.
  const purchaseStockKey=({katchi:'kachi',kachi:'kachi','kachi bricks':'kachi','grade a':'a','grade b':'b','grade c':'c','grade d':'d','barshi awwal':'b','khinger':'c','doem':'d','barshi doem':'e','chullah':'f','chapa':'g',fired:'fired',broken:'broken'})[String(x.item||'').trim().toLowerCase()];
  if(purchaseStockKey){d.stock[purchaseStockKey]=num(d.stock[purchaseStockKey])+x.qty}
  if(x.paid){let c=postCash(x.date,'out','Purchase payment - '+x.supplierName,x.paid);x.paidCashId=c?.id||'';if(x.supplierId){let pm=postPayment(x.date,'supplier',x.supplierId,x.paid);x.paidPaymentId=pm?.id||''}}
  if(x.advance){let c=postCash(x.date,'out','Purchase advance payment - '+x.supplierName,x.advance);x.advanceCashId=c?.id||'';if(x.supplierId){let pm=postPayment(x.date,'supplier',x.supplierId,x.advance);x.advancePaymentId=pm?.id||''}}
  log('Purchase posted',x.supplierName);refresh()}
if(p==='daily')f('dailyForm').onsubmit=e=>{e.preventDefault();let x=Object.fromEntries(new FormData(e.target));x.id=uid();x.date=x.date||today();['kachi','pakki','fired','a','b','c','d','e','f','g','broken','fuel'].forEach(k=>x[k]=num(x[k]));if(x.kachi+x.pakki+x.fired+x.a+x.b+x.c+x.d+x.e+x.f+x.g+x.broken<=0)return alert('Enter at least one production quantity.');d.stock.kachi=num(d.stock.kachi);d.stock.pakki=num(d.stock.pakki);d.stock.fired=num(d.stock.fired);d.stock.a=num(d.stock.a);d.stock.b=num(d.stock.b);d.stock.c=num(d.stock.c);d.stock.d=num(d.stock.d);d.stock.e=num(d.stock.e);d.stock.f=num(d.stock.f);d.stock.g=num(d.stock.g);d.stock.broken=num(d.stock.broken);let katchiAvailable=d.stock.kachi+x.kachi;if(x.pakki>katchiAvailable)return alert('Stock exceeded: Katchi. Available Katchi stock: '+katchiAvailable.toLocaleString()+' bricks. Requested Pakki production: '+x.pakki.toLocaleString()+' bricks. Excess: '+(x.pakki-katchiAvailable).toLocaleString()+' bricks.');let pakkiAvailable=d.stock.pakki+x.pakki;if(x.fired>pakkiAvailable)return alert('Stock exceeded: Pakki. Available Pakki stock: '+pakkiAvailable.toLocaleString()+' bricks. Requested Fired production: '+x.fired.toLocaleString()+' bricks. Excess: '+(x.fired-pakkiAvailable).toLocaleString()+' bricks.');let finalGradeProduction=x.a+x.b+x.c+x.d+x.e+x.f+x.g+x.broken;let firedAvailable=d.stock.fired+x.fired;if(finalGradeProduction>firedAvailable){let exceededCategory='Awwal',cumulative=0;for(const item of [['Awwal',x.a],['Barshi Awwal',x.b],['Khinger',x.c],['Doem',x.d],['Barshi Doem',x.e],['Chullah',x.f],['Chapa',x.g],['Broken',x.broken]]){cumulative+=item[1];if(cumulative>firedAvailable){exceededCategory=item[0];break}}return alert('Stock exceeded: Fired. Available Fired stock: '+firedAvailable.toLocaleString()+' bricks. Requested Awwal + Barshi Awwal + Khinger + Doem + Barshi Doem + Chullah + Chapa + Broken production: '+finalGradeProduction.toLocaleString()+' bricks. Excess: '+(finalGradeProduction-firedAvailable).toLocaleString()+' bricks. Exceeded category: '+exceededCategory+'.');}let katchiAfter=d.stock.kachi+x.kachi-x.pakki;let pakkiAfter=d.stock.pakki+x.pakki-x.fired;d.production.push(x);d.stock.kachi=katchiAfter;d.stock.pakki=pakkiAfter;d.stock.fired=firedAvailable-finalGradeProduction;d.stock.a+=x.a;d.stock.b+=x.b;d.stock.c+=x.c;d.stock.d+=x.d;d.stock.e+=x.e;d.stock.f+=x.f;d.stock.g+=x.g;d.stock.broken+=x.broken;log('Daily production',x.date);refresh()}
if(p==='labour')f('labourForm').onsubmit=e=>{e.preventDefault();let x=Object.fromEntries(new FormData(e.target));x.name=x.name.trim();x.id=uid();x.date=x.date||today();x.workerId=x.name.toLowerCase().replace(/\s+/g,'_');x.qty=num(x.qty);x.rate=num(x.rate);x.wage=(x.qty/1000)*x.rate;x.paid=num(x.paid);x.advance=num(x.advance);if(!x.name||x.qty<0||x.rate<0)return alert('Enter a valid labour name, quantity and rate.');if(x.qty===0&&x.rate===0&&x.paid===0&&x.advance===0)return alert('Entry not saved: all quantities and amounts are zero.');d.workers.push(x);if(x.paid){const pc=postCash(x.date,'out','Labour payment - '+x.name,x.paid);x.paidCashId=pc?.id||'';const pp=postPayment(x.date,'labour',x.workerId,x.paid);x.paidPaymentId=pp?.id||''}if(x.advance){const ac=postCash(x.date,'out','Labour advance payment - '+x.name,x.advance);x.advanceCashId=ac?.id||'';const ap=postPayment(x.date,'labour',x.workerId,x.advance);x.advancePaymentId=ap?.id||''}log('Labour entry',x.name);refresh()}
if(p==='expenses')f('expenseForm').onsubmit=e=>{e.preventDefault();let x=Object.fromEntries(new FormData(e.target));x.id=uid();x.date=x.date||today();x.amount=num(x.amount);if(x.amount<=0)return alert('Enter a valid expense amount.');d.expenses.push(x);postCash(x.date,'out','Expense - '+(x.category||''),x.amount);log('Expense',x.category||'Expense');refresh()}
if(p==='fuel')f('fuelForm').onsubmit=e=>{e.preventDefault();let x=Object.fromEntries(new FormData(e.target));x.id=uid();x.date=x.date||today();x.qty=num(x.qty);x.rate=num(x.rate);x.paid=num(x.paid);let total=x.qty*x.rate;if(x.qty<=0||x.rate<0)return alert('Enter a valid fuel/coal quantity and rate.');if(x.paid<0||x.paid>total)return alert('Paid cannot be greater than the fuel/coal total.');x.total=total;d.fuel.push(x);if(x.paid)postCash(x.date,'out','Fuel purchase - '+x.material,x.paid);log('Fuel purchase',x.material);refresh()}
if(p==='stock')f('stockForm').onsubmit=e=>{e.preventDefault();let x=Object.fromEntries(new FormData(e.target));let changed=false;['kachi','pakki','fired','a','b','c','d','e','f','g','broken'].forEach(k=>{let n=num(x[k]);if(n!==0){d.stock[k]+=n;changed=true}});if(!changed)return alert('Enter a stock adjustment.');log('Stock adjustment',x.reason||'Adjustment');refresh()}
if(p==='vehicles')f('vehicleForm').onsubmit=e=>{e.preventDefault();let x=Object.fromEntries(new FormData(e.target));x.number=x.number.trim();if(!x.number)return alert('Enter vehicle number.');x.id=uid();d.vehicles.push(x);log('Vehicle added',x.number);refresh()}
if(p==='users')f('userForm').onsubmit=e=>{e.preventDefault();let x=Object.fromEntries(new FormData(e.target));x.name=x.name.trim();if(!x.name)return alert('Enter user name.');x.id=uid();d.users.push(x);log('User added',x.name);refresh()}
if(p==='settings')f('settingsForm').onsubmit=e=>{e.preventDefault();let x=Object.fromEntries(new FormData(e.target));d.settings=x;save();show(p)}
}
function editPartyProfile(type,id){
 const isCustomer=type==='customer';const list=isCustomer?d.customers:d.suppliers;const row=list.find(x=>String(x.id)===String(id));if(!row)return alert('Profile not found.');
 const overlay=document.createElement('div');overlay.className='sa-overlay';overlay.style.display='flex';overlay.style.zIndex='9999';
 overlay.innerHTML=`<div class="sa-modal" style="width:min(600px,calc(100vw - 32px));max-width:600px;max-height:82vh;overflow:auto;box-sizing:border-box;padding:16px;margin:auto"><div class="sa-head" style="padding:0;margin:0 0 12px;background:transparent;border:0;box-shadow:none"><h2 style="margin:0">Edit ${isCustomer?'Customer':'Supplier'} Profile</h2></div><form id="editPartyProfileForm"><div class="grid"><div class="field"><label>Company / Name</label><input name="name" value="${esc(row.name||'')}" required></div><div class="field"><label>Phone</label><input name="phone" value="${esc(row.phone||'')}"></div><div class="field"><label>Address</label><input name="address" value="${esc(row.address||'')}"></div>${isCustomer?'':`<div class="field"><label>Item</label><select name="item" ondblclick="enableManualItem(this)" required><option value="">Select item</option>${[['soil','Soil'],['sand','Sand'],['coal','Coal'],['wood','Wood']].map(v=>`<option value="${v[0]}" ${String(row.item||'')===v[0]?'selected':''}>${v[1]}</option>`).join('')}${row.item&&!['soil','sand','coal','wood'].includes(String(row.item))?`<option value="${esc(row.item)}" selected>${esc(row.item)}</option>`:''}</select></div>`}</div><div class="actions" style="margin-top:12px"><button type="submit" class="btn">Save Changes</button><button type="button" class="btn gray" data-close>Cancel</button></div></form></div>`;
 document.body.appendChild(overlay);overlay.querySelector('[data-close]').onclick=()=>overlay.remove();
 overlay.querySelector('#editPartyProfileForm').onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));values.name=String(values.name||'').trim();if(!values.name)return alert('Enter company / name.');if(!isCustomer){values.item=String(values.item||'').trim();if(!values.item)return alert('Select or enter a supplier item.');}const oldName=row.name;Object.assign(row,values);if(isCustomer){d.sales.forEach(s=>{if(s.customerId===row.id)s.customerName=row.name});}else{d.purchases.forEach(p=>{if(p.supplierId===row.id)p.supplierName=row.name});}log((isCustomer?'Customer':'Supplier')+' profile edited',oldName+' → '+row.name);overlay.remove();refresh()};
}

function editRecord(type,id){
 const groups={sale:d.sales,purchase:d.purchases,labour:d.workers,cash:d.cash,vehicle:d.vehicles,user:d.users};
 const row=(groups[type]||[]).find(x=>String(x.id)===String(id));if(!row)return alert('Record not found.');
 const fields={sale:[['date','Date','date'],['customerName','Customer','text'],['brickType','Brick Type','select',[['a','Awwal'],['b','Barshi Awwal'],['c','Khinger'],['d','Doem'],['e','Barshi Doem'],['f','Chullah'],['g','Chapa'],['broken','Broken']]],['qty','Quantity (bricks)','number'],['rate','Rate per Thousand Bricks','number'],['paid','Received','number'],['advanceReceived','Advance Received','number'],['vehicle','Vehicle / Driver','text'],['destination','Destination','text']],purchase:[['supplierName','Supplier','text'],['date','Date','date'],['item','Item','select',[['soil','Soil'],['sand','Sand'],['coal','Coal'],['wood','Wood']]],['qty','Quantity','number'],['qtyUnit','Unit','select',[['kg','kg'],['maund','maund'],['ton','ton'],['trolley','trolley'],['dumper','dumper']]],['rate','Rate','number'],['ratePer','Rate Unit','select',[['kg','kg'],['maund','maund'],['ton','ton'],['trolley','trolley'],['dumper','dumper']]],['paid','Paid Now','number'],['advance','Advance Payment','number']],labour:[['name','Labour / Team Name','text'],['date','Date','date'],['work','Work Type','text'],['qty','Quantity','number'],['rate','Rate per Thousand','number'],['paid','Payment','number'],['advance','Advance Payment','number']],cash:[['date','Date','date'],['type','Type','select',[['in','Cash In'],['out','Cash Out']]],['description','Description','text'],['amount','Amount (Rs.)','number']],vehicle:[['number','Vehicle Number','text'],['type','Vehicle Type','text'],['driver','Driver Name','text'],['phone','Phone','text'],['owner','Owner','text']],user:[['name','Full Name','text'],['username','Username','text'],['role','Role','text']]}[type]||[];
 const controls=fields.map(([key,label,kind,opts])=>{let value=row[key]??'';if(kind==='date')value=String(value||today()).slice(0,10);if(kind==='select'){const choices=[...(opts||[])];if(value!==''&&!choices.some(([v])=>String(v)===String(value)))choices.push([String(value),String(value)]);const manualAttr=(type==='purchase'&&key==='item')?' ondblclick="enableManualItem(this)"':(type==='purchase'&&key==='qtyUnit')?' ondblclick="enableManualQtyUnit(this)"':(type==='purchase'&&key==='ratePer')?' ondblclick="enableManualRatePer(this)"':'';return `<div class="field"><label>${label}</label><select name="${key}"${manualAttr}>${choices.map(([v,t])=>`<option value="${v}" ${String(value)===String(v)?'selected':''}>${t}</option>`).join('')}</select></div>`;}return `<div class="field"><label>${label}</label><input name="${key}" type="${kind}" value="${esc(value)}" ${kind==='number'?'step="any" min="0"':''} ${key==='date'?'required':''}></div>`}).join('');
 const overlay=document.createElement('div');overlay.className='sa-overlay';overlay.style.display='flex';overlay.style.zIndex='9999';overlay.innerHTML=`<div class="sa-modal" style="width:min(760px,calc(100vw - 32px));max-width:760px;max-height:82vh;height:auto;min-height:0;overflow:auto;box-sizing:border-box;padding:12px;margin:auto"><div class="sa-head" style="padding:0;margin:0 0 8px;background:transparent;border:0;box-shadow:none"><h2 style="margin:0">Edit ${({sale:'Sale Entry',purchase:'Purchase Entry',labour:'Labour Entry',cash:'Cash Entry',vehicle:'Vehicle Entry',user:'User Entry'}[type]||'Entry')}</h2></div><form id="editRecordForm"><div class="grid" style="gap:8px;align-content:start">${controls}</div><div class="actions" style="margin-top:9px;padding-bottom:0"><button type="submit" class="btn">Save Changes</button><button type="button" class="btn gray" data-close>Cancel</button></div></form></div>`;
 document.body.appendChild(overlay);overlay.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>overlay.remove());
 overlay.querySelector('#editRecordForm').onsubmit=e=>{e.preventDefault();const next=Object.fromEntries(new FormData(e.target));for(const k of ['qty','rate','paid','advanceReceived','advance','amount'])if(k in next)next[k]=num(next[k]);if(applyEditedRecord(type,id,next)!==false)overlay.remove()};
}
function applyEditedRecord(type,id,next){
 const groups={sale:d.sales,purchase:d.purchases,labour:d.workers,cash:d.cash,vehicle:d.vehicles,user:d.users};const row=(groups[type]||[]).find(x=>String(x.id)===String(id));if(!row)return false;
 // Apply the same entry validations before changing any existing record.
 if(type==='sale'){
  next.customerName=String(next.customerName||'').trim();
  next.customerId=d.customers.find(c=>String(c.name||'').trim().toLowerCase()===next.customerName.toLowerCase())?.id||'';
  next.qty=num(next.qty);next.rate=num(next.rate);next.paid=num(next.paid);next.advanceReceived=num(next.advanceReceived);
  const total=next.qty/1000*next.rate;
  const paymentOnly=next.qty===0&&next.rate===0&&next.paid>0&&next.advanceReceived===0;
  const advanceOnly=next.qty===0&&next.rate===0&&next.paid===0&&next.advanceReceived>0;
  if(next.qty<0||next.rate<0)return alert('Enter a valid quantity and rate.'),false;
  if(next.paid<0||(!paymentOnly&&next.paid>total))return alert('Received cannot be greater than the sale total.'),false;
  if(next.advanceReceived<0)return alert('Advance Received cannot be negative.'),false;
  if(next.advanceReceived>0&&!next.customerId)return alert('Advance Received is not allowed for Cash / Walk-in customer.'),false;
  if(next.qty===0&&next.rate===0&&next.paid===0&&next.advanceReceived===0&&total===0)return alert('Entry not saved: all quantities and amounts are zero.'),false;
  if(next.paid>0&&!paymentOnly&&(next.qty<=0||next.rate<=0))return alert('Enter Quantity and Rate before entering or posting Received.'),false;
  if(paymentOnly){
   if(!next.customerId)return alert('Select a registered customer to record a payment against their outstanding balance.'),false;
   const previousRemaining=d.sales.filter(s=>s.id!==row.id&&s.customerId===next.customerId).reduce((sum,s)=>{const saleTotal=(s.total!==undefined&&s.total!==null&&s.total!=='')?num(s.total):(num(s.qty)/1000)*num(s.rate);return sum+saleTotal-num(s.paid)-num(s.advanceReceived)},0);
   if(previousRemaining<=0)return alert('This customer has no outstanding balance to receive against.'),false;
   if(next.paid>previousRemaining+0.000001)return alert('Received amount cannot be greater than the customer’s previous remaining balance of Rs '+previousRemaining.toLocaleString('en-PK',{maximumFractionDigits:2})+'.'),false;
  }else if(!next.customerId&&next.paid!==total)return alert('Received must be the full Total Amount for Cash / Walk-in customer.'),false;
  if(advanceOnly&&!next.customerName)return alert('Enter customer name for advance received.'),false;
  if(!next.brickType&&!paymentOnly&&!advanceOnly)return alert('Select a brick type.'),false;
  const oldMovesStock=!row.isAdvanceOnly&&!row.isPaymentOnly;
  const newMovesStock=!paymentOnly&&!advanceOnly;
  const available=num(d.stock[next.brickType])+(oldMovesStock&&row.brickType===next.brickType?num(row.qty):0);
  if(newMovesStock&&next.qty>available){const stockName=({a:'Awwal',b:'Barshi Awwal',c:'Khinger',d:'Doem',e:'Barshi Doem',f:'Chullah',g:'Chapa',broken:'Broken'}[next.brickType]||'Brick');return alert(stockName+' stock exceeded. Available stock after accounting for this existing entry: '+available.toLocaleString()+' bricks. Requested for sale: '+next.qty.toLocaleString()+' bricks. Excess: '+(next.qty-available).toLocaleString()+' bricks.'),false;}
  const oldKey=row.brickType,oldQty=num(row.qty);
  if(oldMovesStock&&oldKey)d.stock[oldKey]=num(d.stock[oldKey])+oldQty;
  Object.assign(row,next);row.qty=num(row.qty);row.rate=num(row.rate);row.paid=num(row.paid);row.advanceReceived=num(row.advanceReceived);row.total=row.qty/1000*row.rate;row.isPaymentOnly=paymentOnly;row.isAdvanceOnly=advanceOnly;
  if(newMovesStock)d.stock[row.brickType]=num(d.stock[row.brickType])-row.qty;
  const c=d.cash.find(c=>c.id===row.paidCashId);if(c)c.amount=row.paid;const a=d.cash.find(c=>c.id===row.advanceCashId);if(a)a.amount=row.advanceReceived;
  const pm=d.payments.find(p=>p.id===row.paidPaymentId);if(pm)pm.amount=row.paid;const ap=d.payments.find(p=>p.id===row.advancePaymentId);if(ap)ap.amount=row.advanceReceived;
 }else if(type==='purchase'){
  next.supplierName=String(next.supplierName||'').trim();const matchedSupplier=d.suppliers.find(c=>String(c.name||'').trim().toLowerCase()===next.supplierName.toLowerCase());next.supplierId=matchedSupplier?.id||(next.supplierName.toLowerCase()===String(row.supplierName||'').trim().toLowerCase()?row.supplierId||'':'');
  next.qty=num(next.qty);next.rate=num(next.rate);next.paid=num(next.paid);next.advance=num(next.advance);const total=next.qty*next.rate;
  if(next.qty===0&&next.rate===0&&next.paid===0&&next.advance===0)return alert('Entry not saved: all quantities and amounts are zero.'),false;
  if(next.qty<0||next.rate<0)return alert('Enter a valid quantity and rate.'),false;
  if(next.paid<0||next.advance<0)return alert('Paid Now and Advance Payment cannot be negative.'),false;
  if(next.paid>0&&(next.qty<=0||next.rate<=0))return alert('Enter Quantity and Rate before entering or posting Paid Now.'),false;
  if(next.advance>0&&!next.supplierId)return alert('Advance Payment is not allowed for Cash / Walk-in supplier. Select a registered supplier to use Advance Payment.'),false;
  if(total>0&&next.paid+next.advance>total)return alert('Paid Now plus Advance Payment cannot be greater than the purchase total.'),false;
  if(!next.supplierId&&next.paid!==total)return alert('Cash / Walk-in purchases must be fully paid in Paid Now. Advance Payment is not allowed.'),false;
  const oldItem=row.item,oldQty=num(row.qty);const keyMap={katchi:'kachi',kachi:'kachi','kachi bricks':'kachi','grade a':'a','grade b':'b','grade c':'c','grade d':'d','barshi awwal':'b',khinger:'c',doem:'d','barshi doem':'e',chullah:'f',chapa:'g',fired:'fired',broken:'broken'};const oldKey=keyMap[String(oldItem||'').trim().toLowerCase()];if(oldKey)d.stock[oldKey]=Math.max(0,num(d.stock[oldKey])-oldQty);
  Object.assign(row,next);row.qty=num(row.qty);row.rate=num(row.rate);row.paid=num(row.paid);row.advance=num(row.advance);row.total=row.qty*row.rate;row.balance=row.total-row.paid-row.advance;const newKey=keyMap[String(row.item||'').trim().toLowerCase()];if(newKey)d.stock[newKey]=num(d.stock[newKey])+row.qty;
  const c=d.cash.find(c=>c.id===row.paidCashId);if(c)c.amount=row.paid;const pm=d.payments.find(p=>p.id===row.paidPaymentId);if(pm)pm.amount=row.paid;const ac=d.cash.find(c=>c.id===row.advanceCashId);if(ac)ac.amount=row.advance;const ap=d.payments.find(p=>p.id===row.advancePaymentId);if(ap)ap.amount=row.advance;
 }else if(type==='labour'){
  next.name=String(next.name||'').trim();next.qty=num(next.qty);next.rate=num(next.rate);next.paid=num(next.paid);next.advance=num(next.advance);
  if(!next.name||next.qty<0||next.rate<0)return alert('Enter a valid labour name, quantity and rate.'),false;
  if(next.qty===0&&next.rate===0&&next.paid===0&&next.advance===0)return alert('Entry not saved: all quantities and amounts are zero.'),false;
  Object.assign(row,next);row.qty=num(row.qty);row.rate=num(row.rate);row.paid=num(row.paid);row.advance=num(row.advance);row.wage=row.qty/1000*row.rate;
  const c=d.cash.find(c=>c.id===row.paidCashId);if(c)c.amount=row.paid;const a=d.cash.find(c=>c.id===row.advanceCashId);if(a)a.amount=row.advance;
  const pm=d.payments.find(p=>p.id===row.paidPaymentId);if(pm)pm.amount=row.paid;const ap=d.payments.find(p=>p.id===row.advancePaymentId);if(ap)ap.amount=row.advance;
 }else if(type==='cash'){
  next.amount=num(next.amount);if(!validAmount(next.amount)||next.amount<=0)return alert('Enter a valid amount greater than 0.'),false;Object.assign(row,next);
 }else if(type==='vehicle'){
  next.number=String(next.number||'').trim();if(!next.number)return alert('Enter vehicle number.'),false;Object.assign(row,next);
 }else if(type==='user'){
  next.name=String(next.name||'').trim();if(!next.name)return alert('Enter user name.'),false;Object.assign(row,next);
 }else Object.assign(row,next);
 log((type.charAt(0).toUpperCase()+type.slice(1))+' entry edited',id);refresh();return true;
}

function del(type,id){
if(!confirm('Delete this record?'))return;
if(type==='cash'){d.cash=d.cash.filter(x=>x.id!==id);log('Cash entry deleted',id)}
else if(type==='customer'){if(d.sales.some(x=>x.customerId===id)||d.payments.some(x=>x.type==='customer'&&x.accountId===id))return alert('This customer has linked transactions. Delete or settle those transactions first.');d.customers=d.customers.filter(x=>x.id!==id);log('Customer deleted',id)}
else if(type==='supplier'){if(d.purchases.some(x=>x.supplierId===id)||d.payments.some(x=>x.type==='supplier'&&x.accountId===id))return alert('This supplier has linked transactions. Delete or settle those transactions first.');d.suppliers=d.suppliers.filter(x=>x.id!==id);log('Supplier deleted',id)}
else if(type==='purchase'){let x=d.purchases.find(x=>x.id===id);if(!x)return;d.purchases=d.purchases.filter(x=>x.id!==id);const key=({katchi:'kachi',kachi:'kachi','kachi bricks':'kachi','grade a':'a','grade b':'b','grade c':'c','grade d':'d','barshi awwal':'b','khinger':'c','doem':'d','barshi doem':'e','chullah':'f','chapa':'g',fired:'fired',broken:'broken'})[String(x.item||'').trim().toLowerCase()];if(key)d.stock[key]=Math.max(0,num(d.stock[key])-num(x.qty));if(x.paidCashId)d.cash=d.cash.filter(c=>c.id!==x.paidCashId);if(x.paidPaymentId)d.payments=d.payments.filter(p=>p.id!==x.paidPaymentId);if(x.advanceCashId)d.cash=d.cash.filter(c=>c.id!==x.advanceCashId);if(x.advancePaymentId)d.payments=d.payments.filter(p=>p.id!==x.advancePaymentId);log('Purchase deleted',id)}
else if(type==='sale'){let x=d.sales.find(x=>x.id===id);if(!x)return;d.sales=d.sales.filter(x=>x.id!==id);if(!x.isAdvanceOnly&&x.brickType){d.stock[x.brickType]=num(d.stock[x.brickType])+num(x.qty)}if(x.paidCashId)d.cash=d.cash.filter(c=>c.id!==x.paidCashId);if(x.advanceCashId)d.cash=d.cash.filter(c=>c.id!==x.advanceCashId);if(x.paidPaymentId)d.payments=d.payments.filter(p=>p.id!==x.paidPaymentId);if(x.advancePaymentId)d.payments=d.payments.filter(p=>p.id!==x.advancePaymentId);log('Sale deleted',id)}
else if(type==='labour'){const x=d.workers.find(w=>String(w.id)===String(id));if(!x)return;d.workers=d.workers.filter(w=>String(w.id)!==String(id));if(x.paidCashId||x.advanceCashId){const cashIds=[x.paidCashId,x.advanceCashId].filter(Boolean);d.cash=d.cash.filter(c=>!cashIds.includes(c.id))}else{if(num(x.paid)>0)d.cash=d.cash.filter(c=>!(c.type==='out'&&c.date===x.date&&c.description==='Labour payment - '+x.name&&num(c.amount)===num(x.paid)));if(num(x.advance)>0)d.cash=d.cash.filter(c=>!(c.type==='out'&&c.date===x.date&&c.description==='Labour advance payment - '+x.name&&num(c.amount)===num(x.advance)))}const paymentIds=[x.paidPaymentId,x.advancePaymentId].filter(Boolean);if(paymentIds.length)d.payments=d.payments.filter(p=>!paymentIds.includes(p.id));else{if(num(x.paid)>0)d.payments=d.payments.filter(p=>!(p.type==='labour'&&p.accountId===x.workerId&&p.date===x.date&&num(p.amount)===num(x.paid)));if(num(x.advance)>0)d.payments=d.payments.filter(p=>!(p.type==='labour'&&p.accountId===x.workerId&&p.date===x.date&&num(p.amount)===num(x.advance)))}log('Labour entry deleted',id)}
else if(type==='vehicle'){d.vehicles=d.vehicles.filter(x=>x.id!==id);log('Vehicle deleted',id)}
else if(type==='user'){d.users=d.users.filter(x=>x.id!==id);log('User deleted',id)}
refresh()
}
function backup(){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(d,null,2)],{type:'application/json'}));a.download='bhatta-pro-backup-'+today()+'.json';a.click()}
